#include "server1/archive/ArchiveSources.h"
#include <QCoreApplication>
#include <QTcpServer>
#include <QTcpSocket>
#include <QElapsedTimer>
#include <iostream>
int main(int argc,char **argv){QCoreApplication app(argc,argv);QTcpServer server;server.listen(QHostAddress::LocalHost);QObject::connect(&server,&QTcpServer::newConnection,&server,[&]{while(auto socket=server.nextPendingConnection()){auto input=std::make_shared<QByteArray>();QObject::connect(socket,&QTcpSocket::disconnected,socket,&QObject::deleteLater);QObject::connect(socket,&QTcpSocket::readyRead,socket,[socket,input]{*input+=socket->readAll();if(!input->contains("\r\n\r\n"))return;auto path=input->split(' ').value(1);QByteArray range="Content-Range: bytes 2-5/10\r\n",length="Content-Length: 4\r\n",body="cdef";if(path=="/missing")range.clear();if(path=="/wrong")range="Content-Range: bytes 1-4/10\r\n";if(path=="/unknown")range="Content-Range: bytes 2-5/*\r\n";if(path=="/length")length="Content-Length: 3\r\n";if(path=="/no-length")length.clear();if(path=="/oversized"){length="Content-Length: 5\r\n";body="cdefg";}if(path=="/short")body="cd";socket->write("HTTP/1.1 200 OK\r\nConnection: close\r\n"+range+length+"\r\n"+body);socket->disconnectFromHost();});}});int failures=0;for(auto path:{"/ok","/missing","/wrong","/unknown","/length","/no-length","/oversized","/short"}){server1::archive::RemoteByteSource source(QUrl(QString("http://127.0.0.1:%1%2").arg(server.serverPort()).arg(path)));bool done=false;source.read(2,4,[&](auto result){bool valid=QString(path)=="/ok"?result.error.isEmpty()&&result.status==200&&result.bytes=="cdef"&&result.totalLength==10:!result.error.isEmpty();if(!valid){++failures;std::cerr<<path<<" unexpected response\n";}done=true;});QElapsedTimer timer;timer.start();while(!done&&timer.elapsed()<3000)app.processEvents();if(!done)++failures;}std::cout<<"bounded NZB200 range failures="<<failures<<'\n';return failures?1:0;}
